firmware:
const int BTN = 4;
const int BUZZ = 13;
int last = HIGH;

void beep(int ms) {
  unsigned long end = millis() + ms;
  while (millis() < end) {
    digitalWrite(BUZZ, HIGH);
    delayMicroseconds(250);
    digitalWrite(BUZZ, LOW);
    delayMicroseconds(250);
  }
}

void setup() {
  Serial.begin(115200);
  pinMode(BTN, INPUT_PULLUP);
  pinMode(BUZZ, OUTPUT);
}

void loop() {
  int now = digitalRead(BTN);
  if (last == HIGH && now == LOW) {
    delay(30);
    if (digitalRead(BTN) == LOW) {
      beep(200);
      Serial.println("BEEP");
    }
  }
  last = now;
  delay(5);
}
